#include "target_arithmetic.hpp"
int main(int argc,char** argv){try{
    require(argc==5,"usage: target_signed INPUT-directory BASELINE.json SIGNED.json OUTPUT.json");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input level;auto model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),baseline=read_json(argv[2]),result=read_json(argv[3]);EBPoly f;for(const auto& term:model.at("terms").arr){auto e=term.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(term.at("coefficient").scalar)));}QuarticKM km(model,baseline.at("pool"));
    std::vector<std::array<int,2>> lifts(baseline.at("projected_base").arr.size(),{-1,0});int identity=-1;const auto& images=baseline.at("images").arr;for(size_t i=0;i<images.size();++i){int j=images[i].at("projected_index").integer(),s=images[i].at("sign").integer();if(j<0){require(identity<0,"one identity image");identity=int(i);}else{require(lifts.at(size_t(j))[0]<0,"unique recorded base lift");lifts[size_t(j)]={int(i),s};}}require(identity>=0,"identity lift exists");
    auto zero_row=[&](const std::map<int,int>& row){std::map<int,int> divisor;int degree=0;for(const auto& entry:row){auto lift=lifts.at(size_t(entry.first));require(lift[0]>=0,"recorded signed lift");int coefficient=entry.second*lift[1];divisor[lift[0]]+=coefficient;degree+=coefficient;}divisor[identity]-=degree;std::map<int,int> positive,negative;int d=0,e=0;for(const auto& entry:divisor){if(entry.second>0){positive[entry.first]=entry.second;d+=entry.second;}else if(entry.second<0){negative[entry.first]=-entry.second;e-=entry.second;}}require(d==e&&d<=12,"signed balanced degree cap");int anchor=km.fibers[0].support[0];positive[anchor]+=12-d;negative[anchor]+=12-e;return km.equal(rpa_effective(km,f,positive),rpa_effective(km,f,negative));};
    auto read_row=[&](const Json& sparse){std::map<int,int> row;for(const auto& entry:sparse.arr)row[entry.arr[0].integer()]+=std::stoi(entry.arr[1].scalar);return row;};int baseline_checks=0;for(const auto& row:baseline.at("rows").arr){require(zero_row(read_row(row)),"baseline signed divisor principal");++baseline_checks;}auto corrupt=read_row(baseline.at("rows").arr[0]);++corrupt.begin()->second;require(!zero_row(corrupt),"mutated signed divisor nonprincipal");int principal=0,nonprincipal=0;std::vector<bool> classifications;for(const auto& key:{"signed_rows","halftrace_alias_rows"})for(const auto& row:result.at(key).arr){bool actual=zero_row(read_row(row));classifications.push_back(actual);if(actual)++principal;else ++nonprincipal;}
    std::ofstream out(argv[4]);require(bool(out),"fresh signed target output");out<<"{\"standing\":\"producer-unverified\",\"baseline_principal_checks\":"<<baseline_checks<<",\"mutated_baseline_rejected\":true,\"new_principal_rows\":"<<principal<<",\"new_nonprincipal_norm_rows\":"<<nonprincipal<<",\"target_addflips\":"<<km.flips<<",\"new_curve_points\":0,\"classifications\":[";for(size_t i=0;i<classifications.size();++i)out<<(i?",":"")<<(classifications[i]?"true":"false");out<<"]}\n";require(bool(out),"complete signed target output");
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
